import{_ as n,C as i,o as t,c as s,a2 as a,b as d,w as r,a as l,E as c,a3 as h}from"./chunks/framework.CZqXuAiL.js";const k=JSON.parse('{"title":"OpenShield-L7","description":"L7-protected reverse web proxy in Rust — hostname-routed WAF, rate limiting, PoW challenges, bandwidth quotas and transparent client-IP forwarding in one binary.","frontmatter":{"title":"OpenShield-L7","description":"L7-protected reverse web proxy in Rust — hostname-routed WAF, rate limiting, PoW challenges, bandwidth quotas and transparent client-IP forwarding in one binary."},"headers":[],"relativePath":"openshield-l7/index.md","filePath":"openshield-l7/index.md","lastUpdated":1786524249000}'),p={name:"openshield-l7/index.md"};function u(g,e,b,f,m,S){const o=i("Mermaid");return t(),s("div",null,[e[1]||(e[1]=a('<h1 id="openshield-l7" tabindex="-1">OpenShield-L7 <a class="header-anchor" href="#openshield-l7" aria-label="Permalink to &quot;OpenShield-L7&quot;">​</a></h1><p><strong>An L7-protected reverse web proxy, written in Rust.</strong> OpenShield-L7 is a <em>filter</em>: it sits in front of your destination web servers (<code>ip:port</code>), terminates ports 80/443, and forwards only clean traffic onward. It never hosts content itself — the only bytes it originates are block pages, challenge pages, and the admin API.</p><p>One binary (<code>openshield-l7</code>), one global config file, one YAML file per proxied site. No database, no external services.</p><div class="tip custom-block" style="margin-top:1.5rem;"><p><strong>🛡️ Built for PingLess Studios by <a href="https://github.com/AnAverageBeing" target="_blank" rel="noreferrer">AnAverageBeing</a></strong><a href="https://github.com/AnAverageBeing/openshield-l7" target="_blank" rel="noreferrer">GitHub Repo</a> (currently private) · <code>MIT License</code></p></div><hr><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><h3 id="🌐-hostname-routing-on-80-443" tabindex="-1">🌐 Hostname Routing on 80/443 <a class="header-anchor" href="#🌐-hostname-routing-on-80-443" aria-label="Permalink to &quot;🌐 Hostname Routing on 80/443&quot;">​</a></h3><p>Many sites share one pair of listeners. Exact and wildcard (<code>*.example.com</code>) host matching, case-insensitive, port- and trailing-dot-tolerant. SNI-based certificate selection on 443. Unknown hosts get <code>421</code> — bare-IP scanners never reach a site.</p><h3 id="🔒-optional-per-site-tls" tabindex="-1">🔒 Optional Per-Site TLS <a class="header-anchor" href="#🔒-optional-per-site-tls" aria-label="Permalink to &quot;🔒 Optional Per-Site TLS&quot;">​</a></h3><p>Per-site cert/key with SNI routing (HTTP/2 + HTTP/1.1), HTTP→HTTPS <code>308</code> redirect, optional HSTS. Sites without TLS config simply never get a cert.</p><h3 id="🧱-l7-waf" tabindex="-1">🧱 L7 WAF <a class="header-anchor" href="#🧱-l7-waf" aria-label="Permalink to &quot;🧱 L7 WAF&quot;">​</a></h3><p>SQLi, XSS, path traversal, and RCE pattern sets, scanner/bad-UA blocking, heuristic bot scoring, plus per-site custom regex rules over URI / query / body / method / any header. All matching is linear-time (<code>regex</code> crate) — <strong>no ReDoS</strong>, and input is percent-decoded once before matching.</p><h3 id="🚦-rate-connection-limits" tabindex="-1">🚦 Rate + Connection Limits <a class="header-anchor" href="#🚦-rate-connection-limits" aria-label="Permalink to &quot;🚦 Rate + Connection Limits&quot;">​</a></h3><p>Per-IP and per-site sliding-window request limits, concurrent in-flight connection caps, and automatic temp-bans with escalating durations for repeat offenders (doubling up to 24h). <strong>Auto-mitigation</strong> tightens all of a site&#39;s limits by a configured factor when its RPS crosses a threshold, renewing while the flood continues.</p><h3 id="📋-blacklists-whitelists" tabindex="-1">📋 Blacklists / Whitelists <a class="header-anchor" href="#📋-blacklists-whitelists" aria-label="Permalink to &quot;📋 Blacklists / Whitelists&quot;">​</a></h3><p>A global ACL evaluated before any site logic, plus a per-site ACL. CIDRs or plain IPs, IPv4 and IPv6; the whitelist always wins.</p><h3 id="🧩-js-proof-of-work-challenges" tabindex="-1">🧩 JS Proof-of-Work Challenges <a class="header-anchor" href="#🧩-js-proof-of-work-challenges" aria-label="Permalink to &quot;🧩 JS Proof-of-Work Challenges&quot;">​</a></h3><p>SHA-256 PoW page with HMAC-signed clearance cookies (<code>osc_clear</code>) and server-signed, self-authenticating seeds — fully stateless: the server keeps nothing per client. Modes: <code>off</code> / <code>auto</code> (verdict-driven) / <code>on</code> (challenge everything).</p><h3 id="📊-monthly-quotas-speed-caps" tabindex="-1">📊 Monthly Quotas + Speed Caps <a class="header-anchor" href="#📊-monthly-quotas-speed-caps" aria-label="Permalink to &quot;📊 Monthly Quotas + Speed Caps&quot;">​</a></h3><p>Per-site monthly byte quotas (persisted to disk, reset on a configurable day of month; over-quota sites serve <code>509</code> or drop connections) plus sustained bytes/sec token-bucket caps per site and per client IP.</p><h3 id="🕵️-transparent-client-ip-forwarding" tabindex="-1">🕵️ Transparent Client-IP Forwarding <a class="header-anchor" href="#🕵️-transparent-client-ip-forwarding" aria-label="Permalink to &quot;🕵️ Transparent Client-IP Forwarding&quot;">​</a></h3><p>Five forward modes (<code>none</code> / <code>X-Forwarded-For</code> / <code>X-Real-Ip</code> / <code>Forwarded</code> / custom header), HAProxy PROXY protocol v1/v2, and a Linux <code>IP_TRANSPARENT</code> mode where the origin&#39;s socket table shows the <strong>real client IP</strong> with zero origin configuration. Trusted-proxy-aware resolution walks the XFF chain right-to-left.</p><h3 id="🔥-hot-reload-per-site-configs" tabindex="-1">🔥 Hot-Reload Per-Site Configs <a class="header-anchor" href="#🔥-hot-reload-per-site-configs" aria-label="Permalink to &quot;🔥 Hot-Reload Per-Site Configs&quot;">​</a></h3><p>A file watcher re-parses only the changed file (~300 ms debounce). A broken edit never affects other sites — the last good config keeps serving for the broken one. API writes and file edits are the same pipeline.</p><h3 id="📡-token-secured-admin-api-sse" tabindex="-1">📡 Token-Secured Admin API + SSE <a class="header-anchor" href="#📡-token-secured-admin-api-sse" aria-label="Permalink to &quot;📡 Token-Secured Admin API + SSE&quot;">​</a></h3><p>REST control surface and a live Server-Sent Events telemetry stream on <code>127.0.0.1:9090</code>, role-gated (admin / operator / readonly), with deep per-site analytics: top IPs/paths/UAs/rule hits, latency percentiles, and per-minute RPS/bandwidth series.</p><hr><h2 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./target/release/openshield-l7</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span></span></code></pre></div><p>First run writes a documented default <code>config.yaml</code> and prints one admin token — <strong>once</strong>. Add a site file, and you&#39;re proxying. The full 30-second path is in <a href="./getting-started/quick-start">Quick Start</a>.</p><hr><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2>',32)),(t(),d(h,null,{default:r(()=>[c(o,{id:"mermaid-90",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20CLIENT%5B%22Clients%22%5D%20--%3E%7C%22TCP%20%3A80%22%7C%20HTTP%5B%22listen_http%3Cbr%2F%3Ecleartext%20listeners%22%5D%0A%20%20%20%20CLIENT%20--%3E%7C%22TLS%20%3A443%22%7C%20HTTPS%5B%22listen_https%3Cbr%2F%3ESNI%20cert%20map%22%5D%0A%20%20%20%20HTTP%20--%3E%20ROUTE%5B%22Host%20routing%3Cbr%2F%3EHostIndex%3A%20exact%20%E2%86%92%20wildcard%3Cbr%2F%3E(no%20match%20%E2%86%92%20421)%22%5D%0A%20%20%20%20HTTPS%20--%3E%20ROUTE%0A%0A%20%20%20%20ROUTE%20--%3E%20CHAIN%5B%22Inspector%20chain%20%E2%80%94%20first%20non-Allow%20verdict%20wins%22%5D%0A%20%20%20%20subgraph%20CHAIN_SUB%5B%22%20%22%5D%0A%20%20%20%20%20%20%20%20CHAIN%20--%3E%20S1%5B%221%20%C2%B7%20Ban%20check%20%2B%20IP%20ACL%3Cbr%2F%3E(global%20%E2%86%92%20per-site)%22%5D%0A%20%20%20%20%20%20%20%20S1%20--%3E%20S2%5B%222%20%C2%B7%20Connection%20limits%3Cbr%2F%3Eper-IP%20%2F%20per-site%20in-flight%22%5D%0A%20%20%20%20%20%20%20%20S2%20--%3E%20S3%5B%223%20%C2%B7%20Rate%20limits%3Cbr%2F%3Esliding%20windows%20%2B%20auto-ban%22%5D%0A%20%20%20%20%20%20%20%20S3%20--%3E%20S4%5B%224%20%C2%B7%20WAF%20%2F%20bot%20rules%3Cbr%2F%3Esqli%20%C2%B7%20xss%20%C2%B7%20traversal%20%C2%B7%20rce%20%C2%B7%20scanner%20%C2%B7%20custom%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20S4%20--%3E%7C%22block%20%2F%20challenge%22%7C%20BLOCK%5B%22Block%20page%20403%2F429%2F503%3Cbr%2F%3Eor%20JS%20PoW%20challenge%22%5D%0A%20%20%20%20S4%20--%3E%7C%22allow%22%7C%20THROTTLE%5B%22Throttle%20%2B%20byte%20meter%3Cbr%2F%3Eper-site%20%2F%20per-IP%20bps%20token%20buckets%3Cbr%2F%3Emonthly%20quota%20counters%22%5D%0A%20%20%20%20THROTTLE%20--%3E%20ORIGIN%5B%22Origin%20web%20server%3Cbr%2F%3Eip%3Aport%20%E2%80%94%20pooled%20keep-alive%3Cbr%2F%3EXFF%20%2F%20PROXY%20%2F%20transparent%20source%22%5D%0A%20%20%20%20ORIGIN%20--%3E%7C%22metered%20response%20stream%22%7C%20CLIENT%0A%0A%20%20%20%20subgraph%20ADMIN%5B%22Control%20plane%20(127.0.0.1%3A9090)%22%5D%0A%20%20%20%20%20%20%20%20API%5B%22Admin%20REST%20API%3Cbr%2F%3EBearer%20token%20%C2%B7%20roles%22%5D%0A%20%20%20%20%20%20%20%20SSE%5B%22SSE%20event%20stream%3Cbr%2F%3Erequest%20%C2%B7%20ban%20%C2%B7%20mitigation%20%C2%B7%20reload%22%5D%0A%20%20%20%20%20%20%20%20METRICS%5B%22Metrics%20engine%3Cbr%2F%3Ecounters%20%C2%B7%20ring%20buffers%20%C2%B7%20aggregates%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20CHAIN%20-.-%3E%7C%22one%20event%20per%20request%22%7C%20BUS%5B%22Telemetry%20bus%3Cbr%2F%3E(broadcast%2C%20drop-on-congestion)%22%5D%0A%20%20%20%20THROTTLE%20-.-%3E%20BUS%0A%20%20%20%20BUS%20--%3E%20METRICS%0A%20%20%20%20BUS%20--%3E%20SSE%0A%20%20%20%20API%20--%3E%20METRICS%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h3 id="one-request-s-path" tabindex="-1">One Request&#39;s Path <a class="header-anchor" href="#one-request-s-path" aria-label="Permalink to &quot;One Request&#39;s Path&quot;">​</a></h3><p>Listener → resolve client IP (trusted-proxy aware) → hostname → site config snapshot → inspector chain (first non-<code>Allow</code> verdict wins) → challenge page / block page, or forward to the origin over a pooled keep-alive connection with byte metering and throttling applied to the response stream. Every request produces exactly one telemetry event on the bus, consumed by the metrics engine, the REST analytics endpoints, and the SSE stream.</p><hr><h2 id="comparison" tabindex="-1">Comparison <a class="header-anchor" href="#comparison" aria-label="Permalink to &quot;Comparison&quot;">​</a></h2><p>Factual positioning against the two common self-hosted alternatives: <strong>nginx + ModSecurity (CRS)</strong> and a <strong>hand-assembled Cloudflare-free stack</strong> (nginx + fail2ban + limit_req + scripts).</p><table tabindex="0"><thead><tr><th>Capability</th><th>OpenShield-L7</th><th>nginx + ModSecurity</th><th>Cloudflare-free DIY stack</th></tr></thead><tbody><tr><td>Deployment</td><td>One Rust binary, one global YAML + one YAML per site</td><td>nginx + module + CRS ruleset + tuning</td><td>nginx + fail2ban + cron + scripts</td></tr><tr><td>WAF engine</td><td>Fixed pattern families + custom rules, linear-time regex (no ReDoS)</td><td>OWASP CRS on PCRE — powerful but ReDoS-prone, heavy FP tuning</td><td>Whatever you wire together</td></tr><tr><td>Rate limiting</td><td>Per-IP + per-site sliding windows, escalating auto-bans, RPS-triggered auto-mitigation</td><td><code>limit_req</code> fixed zones; no auto-ban, no auto-tightening</td><td><code>limit_req</code> + fail2ban regexes on logs (seconds of lag)</td></tr><tr><td>Bot challenges</td><td>Built-in stateless JS proof-of-work with HMAC clearance cookies</td><td>None built in</td><td>External (e.g. Anubis, custom pages)</td></tr><tr><td>Client-IP forwarding</td><td>5 header modes + PROXY v1/v2 + <code>IP_TRANSPARENT</code> (origin sees real IP, zero origin config)</td><td>XFF headers only</td><td>XFF (+ PROXY with extra modules)</td></tr><tr><td>Bandwidth quotas</td><td>Monthly per-site byte quotas, persisted, 509/close on exceed</td><td>Not built in</td><td>Not built in</td></tr><tr><td>Speed caps</td><td>Sustained bps token buckets per site and per IP</td><td><code>limit_rate</code> per connection only</td><td><code>limit_rate</code> per connection only</td></tr><tr><td>Hot reload</td><td>Per-file, validated, failure-isolated, atomic swap; API and file edits are one pipeline</td><td>Full config reload; one bad file breaks the whole reload</td><td>Same as nginx</td></tr><tr><td>Admin surface</td><td>Token REST API + SSE events + per-site analytics (tops, latency percentiles, series)</td><td>Access logs</td><td>Access logs + your own parsing</td></tr><tr><td>Content hosting</td><td>Never — reverse proxy only</td><td>Yes (it&#39;s a web server)</td><td>Yes</td></tr><tr><td>Maturity</td><td>New, small codebase you can read end-to-end</td><td>Battle-tested everywhere</td><td>Varies</td></tr></tbody></table><blockquote><p><strong>Bottom line:</strong> if you want a focused L7 filter in front of existing web servers — with challenges, quotas, transparent client IP and a live API built in rather than bolted on — OpenShield-L7 replaces a pile of moving parts with one binary. If you need a general-purpose web server or a decade of CRS rule coverage, nginx + ModSecurity remains the incumbent.</p></blockquote><hr><h2 id="verified-numbers" tabindex="-1">Verified Numbers <a class="header-anchor" href="#verified-numbers" aria-label="Permalink to &quot;Verified Numbers&quot;">​</a></h2><p>From the automated e2e + attack battery (<a href="./architecture/testing">Testing &amp; Benchmarks</a>, <code>testing/RESULTS.md</code>):</p><table tabindex="0"><thead><tr><th>Metric</th><th>Result</th></tr></thead><tbody><tr><td>Unit tests</td><td><strong>215 passed</strong> (<code>cargo test --workspace</code>)</td></tr><tr><td>E2E battery</td><td><strong>85 / 85 passed</strong> (routing, TLS/SNI, XFF modes, WAF, limits, PoW, quotas, API roles, hot reload, bans, SSE, keep-alive, WebSocket, PROXY v1/v2, transparent mode, graceful shutdown)</td></tr><tr><td>Attack scenarios</td><td><strong>8 / 8 passed</strong> (HTTP flood ×2, random-Host flood ×2, POST flood, slowloris, WAF sweep, XFF spoofing)</td></tr><tr><td>HTTP flood absorbed</td><td><strong>152,735 rps</strong> loopback, 100% 429 — benign site kept 100% 200 at p95 2.3 ms</td></tr><tr><td>Random-Host flood</td><td><strong>150,426 rps</strong> → 100% 421, legitimate site untouched</td></tr><tr><td>Proxied throughput (loopback, protections ON)</td><td><strong>67,666 rps</strong> (p50 0.66 ms, p99 1.88 ms, zero errors in 541,881 requests)</td></tr></tbody></table><hr><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><strong><a href="./getting-started/installation">Installation →</a></strong> — Build, systemd, sysctls, verification.</li><li><strong><a href="./getting-started/quick-start">Quick Start →</a></strong> — Proxying a site in 30 seconds.</li><li><strong><a href="./configuration/reference">Configuration Reference →</a></strong> — Every config value, every default.</li><li><strong><a href="./user-guide/cli">CLI Reference →</a></strong> — <code>run</code> / <code>validate</code> / <code>gen-token</code> / <code>gen-cert</code>.</li><li><strong><a href="./user-guide/api">Admin API →</a></strong> — Auth, roles, every endpoint, SSE.</li><li><strong><a href="./architecture/overview">Architecture →</a></strong> — Crates, data flow, threading, event bus.</li><li><strong><a href="./architecture/transparent-ip">Transparent Client IP →</a></strong> — <code>IP_TRANSPARENT</code> deep dive.</li></ul>',14))])}const P=n(p,[["render",u]]);export{k as __pageData,P as default};
